#!/usr/bin/env node
// Bundle budget per route: a deterministic byte count of the built chunks (never a timing).
//   node scripts/check-bundle.mjs                   after `vite build`; exit 1 over budget, 2 when nothing was walked
//   node scripts/check-bundle.mjs --write-baseline  also rewrite budgets/bundle.measured.json (same verdict)
//
// From dist/.vite/manifest.json:
//   entry          the index.html chunk plus everything it imports statically (first load)
//   <page>.l1/.l2  each page layer's lazy chunk plus what it imports beyond the entry
//   door           @shadowrunr/contract's door with its eager validators (ServerFrame + ErrorEnvelope),
//                  loaded in parallel with the first paint; other lazy chunks are named in OTHER_ROUTES
//   goto           the Go to palette (Ctrl+K), loaded on its first open
//   door.result    each method result validator chunk (generated/results/<Def>.js), loaded on that
//                  method's first reply; its line is a PER-CHUNK max, so the largest one is gated
// Budgets live in budgets/bundle.json. A route without a budget, or a budget without a route,
// fails too, so a new page has to declare its budget. Route naming, measuring and the report
// live in bundle-measure.mjs.
//
// budgets/bundle.measured.json is the last accepted measurement: per route js/css and per-chunk
// js under hash-free chunk names. It never blocks; it explains. Each route's row shows its delta
// against it and an over-budget failure lists the chunks that grew. Refresh it whenever a budget
// line is raised or a page change lands its bytes on purpose:
//   pnpm -C apps/console build && pnpm -C apps/console budget:bundle --write-baseline
// and commit it in the same change, so the next raise cites generated figures.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { gzipSync } from "node:zlib";
import { baselineOf, measureRoutes, report } from "./bundle-measure.mjs";

const APP = join(dirname(fileURLToPath(import.meta.url)), "..");
const DIST = join(APP, "dist");
const MANIFEST = join(DIST, ".vite", "manifest.json");
const BUDGETS = JSON.parse(readFileSync(join(APP, "budgets", "bundle.json"), "utf8"));
const BASELINE = join(APP, "budgets", "bundle.measured.json");

if (!existsSync(MANIFEST)) {
  console.error("check-bundle: no dist/.vite/manifest.json (run vite build with build.manifest)");
  process.exit(2);
}
const manifest = JSON.parse(readFileSync(MANIFEST, "utf8"));

const size = (file) => readFileSync(join(DIST, file)).length;
const gz = (file) => gzipSync(readFileSync(join(DIST, file)), { level: 9 }).length;

const measured = measureRoutes(manifest, size, gz);
if (measured.error) {
  console.error(measured.error);
  process.exit(measured.code);
}

if (process.argv.includes("--write-baseline")) {
  const doc = {
    $comment:
      "Generated by `pnpm -C apps/console budget:bundle --write-baseline` after a build: raw minified js/css bytes per route and js per chunk (hash-free names). Report-only - budgets/bundle.json is the gate. Refresh and commit it with every budget raise.",
    routes: baselineOf(measured.routes),
  };
  writeFileSync(BASELINE, `${JSON.stringify(doc, null, 2)}\n`);
  console.log(`check-bundle: wrote ${Object.keys(doc.routes).length} routes to budgets/bundle.measured.json`);
}

const baseline = existsSync(BASELINE) ? JSON.parse(readFileSync(BASELINE, "utf8")).routes : null;
const r = report(measured.routes, BUDGETS.routes, baseline);
for (const line of r.out) console.log(line);
for (const line of r.err) console.error(line);
process.exit(r.code);
